/* ---------------------------------------------------------------- helpers */
const DAY = 86400;
const now = () => Date.now();
const nowS = () => Date.now() / 1000;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const onHosp = () => location.pathname === '/hospitalview.php';
const pct = (p) => (p == null ? '–' : p >= 99.95 ? '100%' : p < 1 ? '<1%' : `${Math.round(p)}%`);
